void addToClassPath(Vector<URL> cpV, String dir) {
    // Get a File object for the directory
    File dirFile = new File(dir);

    // Check if the directory exists
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        // If the directory does not exist or is not a directory, then return
        return;
    }

    // Add all the jar files in the directory to the classpath
    File[] files = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File dir, String name) {
            return name.endsWith(".jar");
        }
    });
    for (File file : files) {
        URL url = file.toURL();
        cpV.add(url);
    }
}

