    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] typeArguments = parameterizedType.getActualTypeArguments();
        TypeVariable<?>[] typeVariables = targetType.getTypeParameters();
        if (typeArguments.length != typeVariables.length) {
            return null;
        }
        Type[] typeVarTypes = new Type[typeArguments.length];
        for (int i = 0; i < typeArguments.length; i++) {
            Type typeArgument = typeArguments[i];
            TypeVariable<?> typeVariable = typeVariables[i];
            if (typeArgument instanceof Class) {
                typeVarTypes[i] = typeArgument;
            } else if (typeArgument instanceof ParameterizedType) {
                ParameterizedType parameterizedTypeArgument = (ParameterizedType) typeArgument;
                Class<?> rawType = parameterizedTypeArgument.getRawType();
                Type[] actualTypes = parameterizedTypeArgument.getActualTypeArguments();
                TypeVariable<?>[] typeArgs = rawType.getTypeParameters();
                if (actualTypes.length != typeArgs.length) {
                    return null;
                }
                Type[] resolvedTypes = new Type[actualTypes.length];
                for (int j = 0; j < actualTypes.length; j++) {
                    resolvedTypes[j] = resolveArgument(typeArguments[j], targetType);
                }
                typeVarTypes[i] = rawType.getConstructor(resolvedTypes).newInstance();
            } else if (typeArgument instanceof TypeVariable) {
                TypeVariable<?> typeVar = (TypeVariable<?>) typeArgument;
                Type bound = typeVar.getBounds()[0];
                if (bound instanceof Class) {
                    typeVarTypes[i] = (Class<?>) bound;
                } else if (bound instanceof ParameterizedType) {
                    typeVarTypes[i] = resolveArgument(bound, targetType);
                } else {
                    typeVarTypes[i] = null;
                }
            }
        }
        return typeVarTypes;
    } else {
        return null;
    }
}

