Node leastCommonAncestor(Node v, Node w) {
  if (v.parent == null && w.parent == null) {
    return -1;
  }
  Node parent1 = v.parent;
  Node parent2 = w.parent;
  while (parent1 != null && parent2 != null) {
    if (parent1 == parent2) {
      return parent1;
    }
    parent1 = parent1.parent;
    parent2 = parent2.parent;
  }
  return -1;
}

public static String reverse(final String str) {
    // check if the input String is null or empty
    if(str == null || str.isEmpty()) {
        // return null if the input String is null or empty
        return str;
    }

    // create a new StringBuilder instance
    StringBuilder sb = new StringBuilder(str.length());

    // loop through the input String from the back and append each character to the StringBuilder
    for(int i=str.length()-1; i>=0; i--) {
        sb.append(str.charAt(i));
    }

    // return the reversed String
    return sb.toString();
}

