public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    int utf8Size = calculateUTF8Size(str);
    lb.writeBytes(new byte[utf8Size]);
    int pos = 0;
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            lb.writeByte((byte)ch);
        } else if (ch < 0x800) {
            lb.writeByte((byte)(0xC0 | (ch >> 6)));
            lb.writeByte((byte)(0x80 | (ch & 0x3F)));
        } else if (ch < 0x10000) {
            lb.writeByte((byte)(0xE0 | (ch >> 12)));
            lb.writeByte((byte)(0x80 | ((ch >> 6) & 0x3F)));
            lb.writeByte((byte)(0x80 | (ch & 0x3F)));
        } else {
            lb.writeByte((byte)(0xF0 | (ch >> 18)));
            lb.writeByte((byte)(0x80 | ((ch >> 12) & 0x3F)));
            lb.writeByte((byte)(0x80 | ((ch >> 6) & 0x3F)));
            lb.writeByte((byte)(0x80 | (ch & 0x3F)));
        }
        pos++;
    }
    return lb;
}

