    }
    try {
        return new URIBuilder(baseUri)
                .setQuery(queryUri.toASCIIString())
                .build();
    } catch (URISyntaxException e) {
        return baseUri;
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (decode) {
        path = URLDecoder.decode(path, StandardCharsets.UTF_8);
    }
    String[] pathSections = path.split("/");
    for (String section : pathSections) {
        if (section.isEmpty()) {
            continue;
        }
        pathSegments.add(new PathSegmentImpl(section));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String rawPath = u.getPath();
    String[] splitPath = rawPath.split("/");
    for (String pathSegment : splitPath) {
        if (decode) {
            pathSegments.add(new PathSegmentImpl(URLDecoder.decode(pathSegment, "UTF-8")));
        } else {
            pathSegments.add(new PathSegmentImpl(pathSegment));
        }
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    if (decode) {
        path = URLDecoder.decode(path, "UTF-8");
    }
    // the path beginning and ending with '/' should be ignored 
    if (path.startsWith("/") && path.endsWith("/")) {
        path = path.substring(1, path.length() - 1);
    }
    // split the path into individual segments
    String[] segmentsArray = path.split("/");
    for (String segment : segmentsArray) {
        segments.add(new PathSegmentImpl(segment, decode));
    }
    return segments;
}

