private void pop(final String descriptor){
    // Loop through each argument type in the descriptor
    for (String argType : descriptor.split(";")) {
        // Get the corresponding stack element
        StackElement stackElem = outputStack.tail();

        // Check if the stack element exists
        if (stackElem == null) {
            throw new IllegalStateException("Error when popping argument from outputStack. Stack is empty.");
        }

        // Check if the stack element has a type matching the argument type
        if (!stackElem.type.equals(argType)) {
            throw new IllegalStateException("Error when popping argument from outputStack. Expected type " + argType +
