public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the width of each half
    double width = box.getWidth() / 2;

    // Create two new boxes with the correct dimensions
    Box2D half1 = new Box2D(box.getX1(), box.getY1(), box.getX1() + width,  box.getY2());
    Box2D half2 = new Box2D(box.getX1() + width, box.getY1(), box.getX2(), box.getY2());

    // Create a pair with the two halves
    Pair<Box2D,Box2D> result = new Pair<Box2D,Box2D>(half1, half2);

    // Return the pair
    return result;
}

public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    double width = box.getWidth();
    double height = box.getHeight();
    double centerX = box.getCenterX();
    double centerY = box.getCenterY();

    double box1Width = width / 2;
    double box1Height = height;
    double box1CenterX = centerX - box1Width / 2;
    double box1CenterY = centerY;

    double box2Width = width / 2;
    double box2Height = height;
    double box2CenterX = centerX + box2Width / 2;
    double box2CenterY = centerY;

    Box2D box1 = new Box2D(box1Width, box1Height, box1CenterX, box1CenterY);
    Box2D box2 = new Box2D(box2Width, box2Height, box2CenterX, box2CenterX);

    return new Pair<>(box1, box2);
}

