}

void removeUnusedNodes() {
  // Traverse the tree in a BFS manner and mark each node as active if it has any active children
  for (Node node : categoryTree.getNodesInOrder()) {
    if (node.isActive()) {
      queue.addLast(node);
    }
  }

  // Traverse the tree in a DFS manner and remove any inactive nodes
  while (!queue.isEmpty()) {
    Node node = queue.pollFirst();
    if (!node.isActive()) {
      if (node.isRoot()) {
        // The root node is inactive, which means the entire tree is inactive
        return 1;
      }
      node.remove();
    } else {
      queue.addLast(node.getChildren());
    }
  }

  return 0;
}

void function ( ) { 
       int inactiveNodes = 0; 

       Node root = categoryTree.getRoot ( ); 
       Stack<Node> stack = new Stack<Node> ( ); 

       List<Node> nodes = new ArrayList<Node> ( ); 

       stack.push (root); 

       while (!stack.empty()) { 
           Node node = stack.pop ( ); 

           inactiveNodes += node.removeState ( false ); 

           if (node.getChildren().size() > 0) { 
               nodes.addAll(node.getChildren()); 
           } 
       } 

       for (Node child : nodes) { 
           inactiveNodes += removeUnusedNodes(child); 
       } 

       return inactiveNodes; 
    }

protected int removeUnusedNodes() {
    Iterator<CategoryNode> iterator = root.descendantIterator();
    while (iterator.hasNext()) {
        CategoryNode node = iterator.next();
        if (!node.isActive()) {
            // Remove this node from the tree by means of a recursive delete
            recursiveDelete(node);
        }
    }
    return root.getDescendantCount();
}

