private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the bucket with the minimum label
    Set<Integer> minBucket = null;
    for (Set<Integer> bucket : bucketsByLabel) {
        if (bucket.size() != 0 && labels.get(labels.indexOf(bucket.first())) == minLabel) {
            minBucket = bucket;
            break;
        }
    }

    // Move all vertices from the minimum bucket to the bucket with label 0
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    for (Integer vertex : minBucket) {
        zeroBucket.add(vertex);
    }

    // Clear the minimum bucket
    minBucket.clear();

    // Update the labeling
    for (Integer vertex : zeroBucket) {
        labels.set(labels.indexOf(vertex), 0);
    }
