    // Move all vertices with label minLabel to the bucket with label 0
    for (Set<Integer> bucket : bucketsByLabel) {
        if (!bucket.isEmpty() && labels.get(bucket.iterator().next()) == minLabel) {
            bucketsByLabel.set(0, bucket);
            bucket.clear();
