public static String applyRelativePath(String path,String relativePath){
    // Replace forward slashes in the relative path with backward slashes
    String normalizedRelativePath = relativePath.replace("/", "\\");
    // Check if the relative path is a Windows path
    if (normalizedRelativePath.startsWith("\\")) {
        // Normalize the path windows-style
        normalizedRelativePath = normalizedRelativePath.substring(1);
        path = path.replace("/", "\\");
    }
    // Apply the relative path to the original path
    return path + normalizedRelativePath;
}

