    String lastPathSegmentWithoutTrailingSlash = lastPathSegment.endsWith("/") ? lastPathSegment.substring(0, lastPathSegment.length() - 1) : lastPathSegment;
    String newPath = lastPathSegmentWithoutTrailingSlash + "/" + relativePathWithoutTrailingSlash;
    return newPath;
}

