    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator == -1) {
        return -1;
    }
    int extensionSeparator = filename.indexOf(DOT_CHAR);
    while (extensionSeparator != -1 && extensionSeparator < lastSeparator) {
        extensionSeparator = filename.indexOf(DOT_CHAR, extensionSeparator + 1);
    }
    return extensionSeparator;
}

