    if (filename == null) {
        return -1;
    }

    // get the index of the last separator character
    int separatorIndex = indexOfLastSeparator(filename);

    // check if there is no directory separator after the last dot
    if (separatorIndex > -1 && filename.charAt(separatorIndex + 1) == '.') {
        return separatorIndex + 1;
    }

    return -1;
}

